namespace sv_1dc56efe47654fa9876db658335f1710.Services;

/// <summary>
/// Stub implementation for development/demo purposes. Replace with a real implementation.
/// </summary>
public class StubChatService : IChatService
{
    private readonly List<Channel> _channels = new()
    {
        new(1, "general", "General discussion for the team", 3),
        new(2, "engineering", "Engineering topics and code reviews", 0),
        new(3, "random", "Off-topic conversations and fun stuff", 1),
    };

    private readonly List<Message> _messages = new()
    {
        new(1, 1, "Alice", "Hey everyone! Welcome to the new team chat.", DateTime.UtcNow.AddHours(-2), null, new() { new("👍", new() { "Bob", "Charlie" }) }),
        new(2, 1, "Bob", "Thanks Alice! This looks great.", DateTime.UtcNow.AddHours(-1.5), null, new()),
        new(3, 1, "Charlie", "Excited to use this!", DateTime.UtcNow.AddMinutes(-45), null, new() { new("🎉", new() { "Alice" }) }),
        new(4, 1, "Alice", "Let me know if you have any questions.", DateTime.UtcNow.AddMinutes(-30), null, new()),
        new(5, 1, "Bob", "Will do! I have a question about the architecture.", DateTime.UtcNow.AddMinutes(-10), 1, new()),
    };

    private int _nextMessageId = 100;

    public Task<List<Channel>> GetChannelsAsync() => Task.FromResult(_channels.ToList());

    public Task<List<Message>> GetMessagesAsync(int channelId, int skip, int take)
    {
        var result = _messages
            .Where(m => m.ChannelId == channelId)
            .OrderBy(m => m.SentAt)
            .Skip(skip)
            .Take(take)
            .ToList();
        return Task.FromResult(result);
    }

    public Task<Message> SendMessageAsync(int channelId, string content, int? replyToId)
    {
        var msg = new Message(Interlocked.Increment(ref _nextMessageId), channelId, "You", content, DateTime.UtcNow, replyToId, new());
        _messages.Add(msg);
        return Task.FromResult(msg);
    }

    public Task<List<Message>> GetThreadAsync(int rootMessageId)
    {
        var replies = _messages.Where(m => m.ReplyToId == rootMessageId).OrderBy(m => m.SentAt).ToList();
        return Task.FromResult(replies);
    }

    public Task AddReactionAsync(int messageId, string emoji)
    {
        var msg = _messages.FirstOrDefault(m => m.Id == messageId);
        if (msg is not null)
        {
            var existing = msg.Reactions.FirstOrDefault(r => r.Emoji == emoji);
            if (existing is not null)
            {
                if (!existing.Users.Contains("You"))
                    existing.Users.Add("You");
            }
            else
